BEGIN;

-- Per-customer, per-currency links from an approved P2 financial identity to a
-- completed P4 customer_statement_entries checkpoint. The opaque scope key is
-- generated by the server adapter and is never accepted from an authenticated client.
CREATE TABLE public.customer_financial_source_statement_scopes (
  organization_id uuid NOT NULL,
  customer_id uuid NOT NULL,
  source_mode text NOT NULL CHECK (source_mode IN ('ONYX','MUTAKAMEL')),
  external_account_ref text NOT NULL CHECK (
    length(btrim(external_account_ref)) BETWEEN 1 AND 160
    AND external_account_ref !~ '://'
    AND position('@' in external_account_ref)=0
  ),
  company_external_ref text NOT NULL CHECK (
    length(btrim(company_external_ref)) BETWEEN 1 AND 256
    AND company_external_ref !~ '://'
    AND position('@' in company_external_ref)=0
  ),
  branch_external_ref text NOT NULL CHECK (
    length(btrim(branch_external_ref)) BETWEEN 1 AND 256
    AND branch_external_ref !~ '://'
    AND position('@' in branch_external_ref)=0
  ),
  currency_code text NOT NULL CHECK (currency_code ~ '^[A-Z]{3}$'),
  scope_key text NOT NULL CHECK (scope_key ~ '^[0-9a-f]{64}$'),
  binding_revision integer NOT NULL CHECK (binding_revision>=1),
  checkpoint_version bigint NOT NULL CHECK (checkpoint_version>=1),
  completed_watermark timestamptz NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT statement_timestamp(),
  updated_at timestamptz NOT NULL DEFAULT statement_timestamp(),
  PRIMARY KEY (organization_id,customer_id,currency_code),
  FOREIGN KEY (organization_id,customer_id)
    REFERENCES public.customer_financial_source_bindings(organization_id,customer_id)
    ON DELETE RESTRICT
);

CREATE INDEX customer_financial_source_statement_scope_lookup
  ON public.customer_financial_source_statement_scopes(organization_id,scope_key);

ALTER TABLE public.customer_financial_source_statement_scopes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.customer_financial_source_statement_scopes FORCE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.customer_financial_source_statement_scopes FROM PUBLIC,anon,authenticated,service_role;

-- Resolve a customer statement scope whenever either half arrives:
-- 1) an authenticated P2 source-sync evidence row, or
-- 2) a completed P4 statement-entry checkpoint.
-- Dynamic SQL keeps the P2 migration installable before P4's optional staging schema
-- is present. The trigger is attached when that schema exists.
CREATE OR REPLACE FUNCTION public.refresh_customer_financial_source_statement_scopes(
  p_organization_id uuid,
  p_customer_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=''
AS $function$
DECLARE
  v_binding public.customer_financial_source_bindings%ROWTYPE;
  v_sync public.customer_financial_source_sync_evidence%ROWTYPE;
  v_provider text;
  v_currency text;
  v_checkpoint record;
  v_rows integer;
BEGIN
  IF p_organization_id IS NULL OR p_customer_id IS NULL
     OR pg_catalog.to_regclass('public.erp_sync_checkpoints') IS NULL THEN
    RETURN;
  END IF;

  SELECT binding.* INTO v_binding
    FROM public.customer_financial_source_bindings binding
   WHERE binding.organization_id=p_organization_id
     AND binding.customer_id=p_customer_id
   FOR SHARE;
  IF NOT FOUND OR v_binding.source_status<>'active'
     OR v_binding.source_mode NOT IN ('ONYX','MUTAKAMEL')
     OR v_binding.external_account_ref IS NULL
     OR v_binding.company_external_ref IS NULL
     OR v_binding.branch_external_ref IS NULL
     OR v_binding.source_as_of IS NULL THEN
    RETURN;
  END IF;

  SELECT evidence.* INTO v_sync
    FROM public.customer_financial_source_sync_evidence evidence
   WHERE evidence.organization_id=p_organization_id
     AND evidence.customer_id=p_customer_id
     AND evidence.source_mode=v_binding.source_mode
     AND evidence.external_account_ref=v_binding.external_account_ref
     AND evidence.company_external_ref=v_binding.company_external_ref
     AND evidence.branch_external_ref=v_binding.branch_external_ref
   ORDER BY evidence.recorded_at DESC,evidence.id DESC
   LIMIT 1;
  IF NOT FOUND OR v_sync.source_as_of IS DISTINCT FROM v_binding.source_as_of
     OR v_sync.currency_codes IS NULL OR cardinality(v_sync.currency_codes) NOT BETWEEN 1 AND 10 THEN
    RETURN;
  END IF;

  v_provider:=CASE v_binding.source_mode
    WHEN 'ONYX' THEN 'onyx_pro'
    WHEN 'MUTAKAMEL' THEN 'al_mutakamel'
    ELSE NULL
  END;
  IF v_provider IS NULL THEN RETURN; END IF;

  FOREACH v_currency IN ARRAY v_sync.currency_codes LOOP
    EXECUTE
      'SELECT scope_key,provider,company_external_id,branch_external_id,' ||
      'warehouse_external_id,currency_code,object_type,version,cursor_ciphertext,' ||
      'pending_watermark,completed_watermark ' ||
      'FROM public.erp_sync_checkpoints ' ||
      'WHERE organization_id=$1 AND provider=$2 AND company_external_id=$3 ' ||
      'AND branch_external_id=$4 AND warehouse_external_id IS NULL ' ||
      'AND currency_code=$5 AND object_type=$6 ' ||
      'ORDER BY version DESC,updated_at DESC LIMIT 1'
      INTO v_checkpoint
      USING p_organization_id,v_provider,v_binding.company_external_ref,
        v_binding.branch_external_ref,v_currency,'customer_statement_entries';
    GET DIAGNOSTICS v_rows=ROW_COUNT;

    IF v_rows=1
       AND v_checkpoint.version>=1
       AND v_checkpoint.cursor_ciphertext IS NULL
       AND v_checkpoint.pending_watermark IS NULL
       AND v_checkpoint.completed_watermark IS NOT NULL
       AND v_checkpoint.completed_watermark>=v_binding.source_as_of
       AND v_checkpoint.completed_watermark<=statement_timestamp()
       AND v_checkpoint.completed_watermark>=statement_timestamp()-interval '24 hours' THEN
      INSERT INTO public.customer_financial_source_statement_scopes(
        organization_id,customer_id,source_mode,external_account_ref,
        company_external_ref,branch_external_ref,currency_code,scope_key,
        binding_revision,checkpoint_version,completed_watermark
      ) VALUES (
        p_organization_id,p_customer_id,v_binding.source_mode,v_binding.external_account_ref,
        v_binding.company_external_ref,v_binding.branch_external_ref,v_currency,v_checkpoint.scope_key,
        v_binding.revision,v_checkpoint.version,v_checkpoint.completed_watermark
      )
      ON CONFLICT (organization_id,customer_id,currency_code)
      DO UPDATE SET
        source_mode=EXCLUDED.source_mode,
        external_account_ref=EXCLUDED.external_account_ref,
        company_external_ref=EXCLUDED.company_external_ref,
        branch_external_ref=EXCLUDED.branch_external_ref,
        scope_key=EXCLUDED.scope_key,
        binding_revision=EXCLUDED.binding_revision,
        checkpoint_version=EXCLUDED.checkpoint_version,
        completed_watermark=EXCLUDED.completed_watermark,
        updated_at=statement_timestamp()
      WHERE public.customer_financial_source_statement_scopes.binding_revision<EXCLUDED.binding_revision
         OR (
           public.customer_financial_source_statement_scopes.binding_revision=EXCLUDED.binding_revision
           AND public.customer_financial_source_statement_scopes.scope_key=EXCLUDED.scope_key
           AND public.customer_financial_source_statement_scopes.external_account_ref=EXCLUDED.external_account_ref
           AND public.customer_financial_source_statement_scopes.company_external_ref=EXCLUDED.company_external_ref
           AND public.customer_financial_source_statement_scopes.branch_external_ref=EXCLUDED.branch_external_ref
         );
    END IF;
  END LOOP;
END
$function$;

REVOKE ALL ON FUNCTION public.refresh_customer_financial_source_statement_scopes(uuid,uuid)
  FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.capture_customer_financial_source_statement_scope_from_sync()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=''
AS $function$
BEGIN
  PERFORM public.refresh_customer_financial_source_statement_scopes(NEW.organization_id,NEW.customer_id);
  RETURN NEW;
END
$function$;
REVOKE ALL ON FUNCTION public.capture_customer_financial_source_statement_scope_from_sync()
  FROM PUBLIC,anon,authenticated,service_role;

CREATE TRIGGER customer_financial_source_statement_scope_from_sync
  AFTER INSERT ON public.customer_financial_source_sync_evidence
  FOR EACH ROW EXECUTE FUNCTION public.capture_customer_financial_source_statement_scope_from_sync();

CREATE OR REPLACE FUNCTION public.capture_customer_financial_source_statement_scope_from_checkpoint()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=''
AS $function$
DECLARE
  v_customer record;
  v_provider_mode text;
BEGIN
  IF NEW.object_type<>'customer_statement_entries'
     OR NEW.currency_code IS NULL
     OR NEW.cursor_ciphertext IS NOT NULL
     OR NEW.pending_watermark IS NOT NULL
     OR NEW.completed_watermark IS NULL THEN
    RETURN NEW;
  END IF;

  v_provider_mode:=CASE NEW.provider
    WHEN 'onyx_pro' THEN 'ONYX'
    WHEN 'al_mutakamel' THEN 'MUTAKAMEL'
    ELSE NULL
  END;
  IF v_provider_mode IS NULL THEN RETURN NEW; END IF;

  FOR v_customer IN
    SELECT binding.organization_id,binding.customer_id
      FROM public.customer_financial_source_bindings binding
     WHERE binding.organization_id=NEW.organization_id
       AND binding.source_mode=v_provider_mode
       AND binding.source_status='active'
       AND binding.company_external_ref=NEW.company_external_id
       AND binding.branch_external_ref=NEW.branch_external_id
  LOOP
    PERFORM public.refresh_customer_financial_source_statement_scopes(
      v_customer.organization_id,v_customer.customer_id
    );
  END LOOP;
  RETURN NEW;
END
$function$;
REVOKE ALL ON FUNCTION public.capture_customer_financial_source_statement_scope_from_checkpoint()
  FROM PUBLIC,anon,authenticated,service_role;

-- If P4 is merged before P2, attach now. If P2 is merged first, P4's own migration
-- performs the same conditional attachment after creating its checkpoint table.
DO $do$
BEGIN
  IF pg_catalog.to_regclass('public.erp_sync_checkpoints') IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM pg_catalog.pg_trigger
        WHERE tgname='customer_financial_source_statement_scope_from_checkpoint'
          AND tgrelid='public.erp_sync_checkpoints'::regclass
          AND NOT tgisinternal
     ) THEN
    EXECUTE
      'CREATE TRIGGER customer_financial_source_statement_scope_from_checkpoint ' ||
      'AFTER UPDATE OF completed_watermark,cursor_ciphertext,pending_watermark ' ||
      'ON public.erp_sync_checkpoints FOR EACH ROW ' ||
      'EXECUTE FUNCTION public.capture_customer_financial_source_statement_scope_from_checkpoint()';
  END IF;
END
$do$;


-- The sync evidence trigger runs before record_customer_financial_source_sync updates
-- the current binding watermark. Re-evaluate after that binding UPDATE as well, so
-- P4-completed scopes map regardless of whether P4 or the P2 provider writer finishes first.
CREATE OR REPLACE FUNCTION public.capture_customer_financial_source_statement_scope_from_binding()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=''
AS $function$
BEGIN
  IF NEW.source_mode IS DISTINCT FROM OLD.source_mode
     OR NEW.source_status IS DISTINCT FROM OLD.source_status
     OR NEW.external_account_ref IS DISTINCT FROM OLD.external_account_ref
     OR NEW.company_external_ref IS DISTINCT FROM OLD.company_external_ref
     OR NEW.branch_external_ref IS DISTINCT FROM OLD.branch_external_ref
     OR NEW.source_as_of IS DISTINCT FROM OLD.source_as_of
     OR NEW.last_synced_at IS DISTINCT FROM OLD.last_synced_at
     OR NEW.revision IS DISTINCT FROM OLD.revision THEN
    PERFORM public.refresh_customer_financial_source_statement_scopes(
      NEW.organization_id,NEW.customer_id
    );
  END IF;
  RETURN NEW;
END
$function$;
REVOKE ALL ON FUNCTION public.capture_customer_financial_source_statement_scope_from_binding()
  FROM PUBLIC,anon,authenticated,service_role;

CREATE TRIGGER customer_financial_source_statement_scope_from_binding
  AFTER UPDATE OF source_mode,source_status,external_account_ref,company_external_ref,
    branch_external_ref,source_as_of,last_synced_at,revision
  ON public.customer_financial_source_bindings
  FOR EACH ROW EXECUTE FUNCTION public.capture_customer_financial_source_statement_scope_from_binding();

-- The customer statement adapter reads only latest accepted P4 outcomes from every
-- registered currency scope. It never reads or mutates operational invoices/payments,
-- never combines different currencies, and refuses partial, stale or conflicted scopes.
CREATE OR REPLACE FUNCTION public.get_customer_account_statement()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=''
AS $function$
DECLARE
  v_profile uuid:=public.current_profile_id();
  v_customer uuid;
  v_org uuid;
  v_locked_customer uuid;
  v_binding public.customer_financial_source_bindings%ROWTYPE;
  v_sync public.customer_financial_source_sync_evidence%ROWTYPE;
  v_scope record;
  v_checkpoint record;
  v_receipt record;
  v_rows integer;
  v_bad_records integer;
  v_scope_count integer;
  v_currencies jsonb:='[]'::jsonb;
  v_currency_statement jsonb;
  v_external_statement jsonb;
  v_app_statement jsonb;
  v_provider text;
BEGIN
  IF auth.uid() IS NULL OR v_profile IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='an authenticated customer account is required';
  END IF;
  SELECT profile.organization_id INTO v_org
    FROM public.profiles profile
    JOIN public.organizations organization
      ON organization.id=profile.organization_id AND organization.is_active=true
   WHERE profile.id=v_profile
     AND profile.auth_user_id=auth.uid()
     AND profile.is_active=true;
  IF v_org IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='active customer organization context required';
  END IF;
  IF NOT public.current_customer_can('statement.read') THEN
    RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='company member is not allowed to read the account statement';
  END IF;

  v_customer:=public.current_customer_id();
  IF v_customer IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='customer account is not linked to the active profile';
  END IF;
  SELECT customer.id INTO v_locked_customer
    FROM public.customers customer
   WHERE customer.id=v_customer
     AND customer.organization_id=v_org
     AND customer.status='approved'
   FOR SHARE;
  IF v_locked_customer IS NULL OR NOT public.current_customer_can('statement.read') THEN
    RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='customer statement access is outside the active customer scope';
  END IF;

  SELECT binding.* INTO v_binding
    FROM public.customer_financial_source_bindings binding
   WHERE binding.organization_id=v_org
     AND binding.customer_id=v_customer
   FOR SHARE;
  IF NOT FOUND OR v_binding.source_status<>'active' THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='customer financial source is not active; statement access is blocked';
  END IF;

  IF v_binding.source_mode='APP_ONLY' THEN
    v_app_statement:=public.get_customer_account_statement_app_only_internal();
    RETURN v_app_statement || pg_catalog.jsonb_build_object('source_mode','APP_ONLY');
  END IF;

  IF v_binding.source_as_of IS NULL
     OR v_binding.source_as_of<statement_timestamp()-interval '24 hours'
     OR v_binding.source_as_of>statement_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='external customer statement source is stale; app ledger fallback is prohibited';
  END IF;

  IF pg_catalog.to_regclass('public.erp_sync_checkpoints') IS NULL
     OR pg_catalog.to_regclass('public.erp_sync_page_receipts') IS NULL
     OR pg_catalog.to_regclass('public.erp_sync_page_record_outcomes') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ERP statement staging is not installed; app ledger fallback is prohibited';
  END IF;

  SELECT evidence.* INTO v_sync
    FROM public.customer_financial_source_sync_evidence evidence
   WHERE evidence.organization_id=v_org
     AND evidence.customer_id=v_customer
     AND evidence.source_mode=v_binding.source_mode
     AND evidence.external_account_ref=v_binding.external_account_ref
     AND evidence.company_external_ref=v_binding.company_external_ref
     AND evidence.branch_external_ref=v_binding.branch_external_ref
   ORDER BY evidence.recorded_at DESC,evidence.id DESC
   LIMIT 1;
  IF NOT FOUND
     OR v_sync.source_as_of IS DISTINCT FROM v_binding.source_as_of
     OR v_sync.source_as_of<statement_timestamp()-interval '24 hours'
     OR v_sync.source_as_of>statement_timestamp()
     OR v_sync.currency_codes IS NULL
     OR cardinality(v_sync.currency_codes) NOT BETWEEN 1 AND 10 THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='external customer statement currency evidence is missing or stale; app ledger fallback is prohibited';
  END IF;

  SELECT count(*)::integer INTO v_scope_count
    FROM public.customer_financial_source_statement_scopes scope
   WHERE scope.organization_id=v_org
     AND scope.customer_id=v_customer
     AND scope.source_mode=v_binding.source_mode
     AND scope.external_account_ref=v_binding.external_account_ref
     AND scope.company_external_ref=v_binding.company_external_ref
     AND scope.branch_external_ref=v_binding.branch_external_ref
     AND scope.binding_revision=v_binding.revision
     AND scope.currency_code=ANY(v_sync.currency_codes);
  IF v_scope_count<>cardinality(v_sync.currency_codes) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='one or more ERP customer statement currency scopes are incomplete; app ledger fallback is prohibited';
  END IF;

  v_provider:=CASE v_binding.source_mode
    WHEN 'ONYX' THEN 'onyx_pro'
    WHEN 'MUTAKAMEL' THEN 'al_mutakamel'
    ELSE NULL
  END;
  IF v_provider IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='configured external customer statement provider is unsupported; app ledger fallback is prohibited';
  END IF;

  FOR v_scope IN
    SELECT scope.*
      FROM public.customer_financial_source_statement_scopes scope
     WHERE scope.organization_id=v_org
       AND scope.customer_id=v_customer
       AND scope.source_mode=v_binding.source_mode
       AND scope.external_account_ref=v_binding.external_account_ref
       AND scope.company_external_ref=v_binding.company_external_ref
       AND scope.branch_external_ref=v_binding.branch_external_ref
       AND scope.binding_revision=v_binding.revision
       AND scope.currency_code=ANY(v_sync.currency_codes)
     ORDER BY scope.currency_code
  LOOP
    v_checkpoint:=NULL;
    EXECUTE
      'SELECT scope_key,provider,company_external_id,branch_external_id,' ||
      'warehouse_external_id,currency_code,object_type,version,cursor_ciphertext,' ||
      'pending_watermark,completed_watermark ' ||
      'FROM public.erp_sync_checkpoints WHERE organization_id=$1 AND scope_key=$2'
      INTO v_checkpoint USING v_org,v_scope.scope_key;
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows<>1
       OR v_checkpoint.provider IS DISTINCT FROM v_provider
       OR v_checkpoint.company_external_id IS DISTINCT FROM v_binding.company_external_ref
       OR v_checkpoint.branch_external_id IS DISTINCT FROM v_binding.branch_external_ref
       OR v_checkpoint.warehouse_external_id IS NOT NULL
       OR v_checkpoint.currency_code IS DISTINCT FROM v_scope.currency_code
       OR v_checkpoint.object_type IS DISTINCT FROM 'customer_statement_entries'
       OR v_checkpoint.version IS DISTINCT FROM v_scope.checkpoint_version
       OR v_checkpoint.completed_watermark IS DISTINCT FROM v_scope.completed_watermark
       OR v_checkpoint.cursor_ciphertext IS NOT NULL
       OR v_checkpoint.pending_watermark IS NOT NULL
       OR v_checkpoint.completed_watermark IS NULL
       OR v_checkpoint.completed_watermark<v_binding.source_as_of
       OR v_checkpoint.completed_watermark<statement_timestamp()-interval '24 hours'
       OR v_checkpoint.completed_watermark>statement_timestamp() THEN
      RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='an ERP customer statement currency scope is stale or incomplete; app ledger fallback is prohibited';
    END IF;

    v_receipt:=NULL;
    EXECUTE
      'SELECT completed,next_cursor_present,completed_watermark ' ||
      'FROM public.erp_sync_page_receipts ' ||
      'WHERE organization_id=$1 AND scope_key=$2 ' ||
      'ORDER BY committed_version DESC,recorded_at DESC LIMIT 1'
      INTO v_receipt USING v_org,v_scope.scope_key;
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows<>1
       OR v_receipt.completed IS DISTINCT FROM true
       OR v_receipt.next_cursor_present IS DISTINCT FROM false
       OR v_receipt.completed_watermark IS DISTINCT FROM v_checkpoint.completed_watermark THEN
      RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='the latest ERP statement page receipt is not a completed snapshot; app ledger fallback is prohibited';
    END IF;

    EXECUTE $query$
      WITH latest_outcomes AS MATERIALIZED (
        SELECT DISTINCT ON (outcome.external_id)
               outcome.external_id,outcome.fields,outcome.disposition,
               outcome.source_updated_at
          FROM public.erp_sync_page_record_outcomes outcome
          JOIN public.erp_sync_page_receipts receipt
            ON receipt.organization_id=outcome.organization_id
           AND receipt.scope_key=outcome.scope_key
           AND receipt.page_fingerprint=outcome.page_fingerprint
         WHERE outcome.organization_id=$1 AND outcome.scope_key=$2
         ORDER BY outcome.external_id,receipt.committed_version DESC,
                  receipt.recorded_at DESC,outcome.recorded_at DESC,
                  outcome.page_fingerprint DESC
      )
      SELECT count(*)::integer
        FROM latest_outcomes latest
       WHERE (
           latest.fields->>'external_customer_id'=$3
           OR nullif(btrim(latest.fields->>'external_customer_id'),'') IS NULL
           OR coalesce(latest.fields->>'external_customer_id','') !~ '^[A-Za-z0-9._:/-]{1,160}$'
           OR latest.disposition NOT IN ('created','updated','unchanged')
           OR latest.fields->>'currency_code' IS DISTINCT FROM $4
           OR jsonb_typeof(latest.fields->'entry_reference') IS DISTINCT FROM 'string'
           OR length(btrim(coalesce(latest.fields->>'entry_reference',''))) NOT BETWEEN 1 AND 160
           OR jsonb_typeof(latest.fields->'entry_type') IS DISTINCT FROM 'string'
           OR (latest.fields->>'entry_type') NOT IN ('invoice','payment','credit_note','debit_note','opening_balance','adjustment')
           OR jsonb_typeof(latest.fields->'entry_date') IS DISTINCT FROM 'string'
           OR (latest.fields->>'entry_date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
           OR CASE
                WHEN (latest.fields->>'entry_date') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
                THEN (latest.fields->>'entry_date')::date IS NULL
                ELSE false
              END
           OR jsonb_typeof(latest.fields->'debit_amount') IS DISTINCT FROM 'string'
           OR coalesce(latest.fields->>'debit_amount','') !~ '^(0|[1-9][0-9]{0,15})([.][0-9]{1,4})?$'
           OR jsonb_typeof(latest.fields->'credit_amount') IS DISTINCT FROM 'string'
           OR coalesce(latest.fields->>'credit_amount','') !~ '^(0|[1-9][0-9]{0,15})([.][0-9]{1,4})?$'
           OR CASE WHEN coalesce(latest.fields->>'debit_amount','') ~ '^(0|[1-9][0-9]{0,15})([.][0-9]{1,4})?$'
                   THEN (latest.fields->>'debit_amount')::numeric>0 ELSE false END
              AND CASE WHEN coalesce(latest.fields->>'credit_amount','') ~ '^(0|[1-9][0-9]{0,15})([.][0-9]{1,4})?$'
                       THEN (latest.fields->>'credit_amount')::numeric>0 ELSE false END
           OR (latest.fields ? 'due_date' AND jsonb_typeof(latest.fields->'due_date')<>'null'
               AND (jsonb_typeof(latest.fields->'due_date') IS DISTINCT FROM 'string'
                    OR (latest.fields->>'due_date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'))
           OR (latest.fields ? 'description' AND jsonb_typeof(latest.fields->'description') NOT IN ('string','null'))
           OR (latest.fields ? 'source_document_number' AND jsonb_typeof(latest.fields->'source_document_number') NOT IN ('string','null'))
         )
      $query$
      INTO v_bad_records
      USING v_org,v_scope.scope_key,v_binding.external_account_ref,v_scope.currency_code;
    IF v_bad_records>0 THEN
      RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ERP customer statement contains rejected or invalid records for this account; app ledger fallback is prohibited';
    END IF;

    EXECUTE $query$
      WITH latest_outcomes AS MATERIALIZED (
        SELECT DISTINCT ON (outcome.external_id)
               outcome.external_id,outcome.fields,outcome.disposition,
               outcome.source_updated_at
          FROM public.erp_sync_page_record_outcomes outcome
          JOIN public.erp_sync_page_receipts receipt
            ON receipt.organization_id=outcome.organization_id
           AND receipt.scope_key=outcome.scope_key
           AND receipt.page_fingerprint=outcome.page_fingerprint
         WHERE outcome.organization_id=$1 AND outcome.scope_key=$2
         ORDER BY outcome.external_id,receipt.committed_version DESC,
                  receipt.recorded_at DESC,outcome.recorded_at DESC,
                  outcome.page_fingerprint DESC
      ),
      account_entries AS MATERIALIZED (
        SELECT latest.external_id,
               latest.fields->>'entry_reference' AS entry_reference,
               (latest.fields->>'entry_date')::date AS entry_date,
               CASE WHEN latest.fields->>'due_date' IS NULL OR latest.fields->>'due_date'=''
                    THEN NULL ELSE (latest.fields->>'due_date')::date END AS due_date,
               latest.fields->>'entry_type' AS entry_type,
               (latest.fields->>'debit_amount')::numeric AS debit_amount,
               (latest.fields->>'credit_amount')::numeric AS credit_amount,
               latest.fields->>'source_document_number' AS source_document_number,
               coalesce(latest.fields->>'description','') AS description
          FROM latest_outcomes latest
         WHERE latest.fields->>'external_customer_id'=$3
           AND latest.disposition IN ('created','updated','unchanged')
      ),
      calculated AS MATERIALIZED (
        SELECT entry.*,
               sum(entry.debit_amount-entry.credit_amount) OVER (
                 ORDER BY entry.entry_date ASC,entry.entry_reference ASC,entry.external_id ASC
                 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
               ) AS running_balance,
               row_number() OVER (
                 ORDER BY entry.entry_date DESC,entry.entry_reference DESC,entry.external_id DESC
               ) AS detail_rank
          FROM account_entries entry
      )
      SELECT pg_catalog.jsonb_build_object(
        'currency_code',$4,
        'source_as_of',$5,
        'entry_count',(SELECT count(*) FROM calculated),
        'total_debit',coalesce((SELECT sum(debit_amount) FROM calculated),0)::text,
        'total_credit',coalesce((SELECT sum(credit_amount) FROM calculated),0)::text,
        'closing_balance',coalesce((
          SELECT running_balance FROM calculated
           ORDER BY entry_date DESC,entry_reference DESC,external_id DESC LIMIT 1
        ),0)::text,
        'details_partial',(SELECT count(*)>500 FROM calculated),
        'entries',coalesce((
          SELECT jsonb_agg(pg_catalog.jsonb_build_object(
            'entry_reference',entry_reference,
            'entry_date',entry_date,
            'due_date',due_date,
            'entry_type',entry_type,
            'debit_amount',debit_amount::text,
            'credit_amount',credit_amount::text,
            'running_balance',running_balance::text,
            'source_document_number',source_document_number,
            'description',description
          ) ORDER BY entry_date DESC,entry_reference DESC,external_id DESC)
            FROM calculated WHERE detail_rank<=500
        ),'[]'::jsonb)
      )
      $query$
      INTO v_currency_statement
      USING v_org,v_scope.scope_key,v_binding.external_account_ref,
        v_scope.currency_code,v_checkpoint.completed_watermark;

    v_currencies:=v_currencies || pg_catalog.jsonb_build_array(v_currency_statement);
  END LOOP;

  v_external_statement:=pg_catalog.jsonb_build_object(
    'source_mode',v_binding.source_mode,
    'source_as_of',v_binding.source_as_of,
    'currencies',v_currencies,
    'details_limit_per_currency',500
  );
  RETURN pg_catalog.jsonb_build_object(
    'source_mode',v_binding.source_mode,
    'summary_as_of_utc',v_binding.source_as_of,
    'invoices','[]'::jsonb,
    'payments','[]'::jsonb,
    'credits','[]'::jsonb,
    'summary',NULL,
    'external_statement',v_external_statement
  );
END
$function$;

REVOKE ALL ON FUNCTION public.get_customer_account_statement() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_customer_account_statement() TO authenticated;
COMMENT ON FUNCTION public.get_customer_account_statement() IS
  'Routes APP_ONLY customers to the internal statement. ONYX/MUTAKAMEL customers receive only their own latest accepted P4 staged statement entries, per-currency balances and completed-scope watermarks. Stale, partial, conflicted or unmapped ERP scopes fail closed; there is no APP_ONLY fallback.';

COMMIT;
